// src/settings/index.ts
var import_obsidian14 = require("obsidian");

// src/settings/FolderSuggester.ts
var import_obsidian12 = require("obsidian");
var FolderSuggest = class extends import_obsidian12.AbstractInputSuggest {
  constructor(inputEl, app) {
    super(app, inputEl);
    this.inputEl = inputEl;
    this.app = app;
  }
  getSuggestions(inputStr) {
    const lowerCaseInputStr = inputStr.toLowerCase();
    return this.app.vault.getAllFolders(true).filter(
      (folder) => folder.path.toLowerCase().contains(lowerCaseInputStr)
    );
  }
  renderSuggestion(file, el2) {
    el2.setText(file.path);
  }
  selectSuggestion(file) {
    this.inputEl.value = file.path;
    this.inputEl.trigger("input");
    this.close();
  }
};

