// src/modals/Confirm.ts
var import_obsidian13 = require("obsidian");
var ConfirmModal = class extends import_obsidian13.Modal {
  constructor(app) {
    super(app);
    this.buttonContainerEl = this.modalEl.createDiv("modal-button-container");
    this.resolve = null;
    this.containerEl.addClass("mod-confirmation");
    this.addButton("mod-cta", "OK", () => {
      if (this.resolve) this.resolve(true);
    });
    this.addCancelButton();
  }
  // eslint-disable-next-line @typescript-eslint/no-misused-promises -- intentionally returns Promise for await usage
  open() {
    super.open();
    return new Promise((resolve) => this.resolve = resolve);
  }
  addButton(cls, text4, callback) {
    this.buttonContainerEl.createEl("button", { cls, text: text4 }).addEventListener("click", (evt) => {
      if (callback) void callback(evt);
      this.close();
    });
    return this;
  }
  onClose() {
    if (this.resolve) this.resolve(false);
  }
  addCancelButton() {
    return this.addButton("", "Cancel", this.close.bind(this));
  }
};
var confirm = (message, app) => {
  const modal = new ConfirmModal(app);
  modal.contentEl.setText(message);
  return modal.open();
};

